#!/usr/bin/env node
'use strict';
const fs=require('node:fs'),cp=require('node:child_process');
const D='/Users/mac/.codex/asg-observer',LOG=D+'/events.jsonl',PY='/Library/Developer/CommandLineTools/usr/bin/python3',CLIENT='/Users/mac/个人项目/asg-os-sensor-advisor-20260911/runtime/hook_control_client.py',CFG='/Users/mac/个人项目/asg-os-sensor-advisor-20260911/artifacts/stage1/dashboard/hook-control-client.json',MAX_FIELD_BYTES=1048576;
const MAP={SessionStart:'hook.loaded',UserPromptSubmit:'user.input',PreToolUse:'tool.execute.before',PostToolUse:'tool.execute.after',Stop:'assistant.output'},BAD=/(token|secret|password|api[_-]?key|authorization|cookie)/i;
function clean(v,k,p,m){if(typeof v==='string'){if(BAD.test(k||''))return'[REDACTED]';let n=Buffer.byteLength(v);if(n<=MAX_FIELD_BYTES)return v;let x=Buffer.from(v).subarray(0,MAX_FIELD_BYTES).toString();m.push({field:p,original_bytes:n,retained_bytes:Buffer.byteLength(x),truncated:true});return x}if(v===null||typeof v==='number'||typeof v==='boolean')return v;if(Array.isArray(v))return v.map((x,i)=>clean(x,k,p+'['+i+']',m));if(typeof v==='object'){let o={};for(let x of Object.keys(v))o[x]=clean(v[x],x,p+'.'+x,m);return o}return null}
function pid(){let p=Number(process.env.ASG_AGENT_PID);if(p>1)return p;return null}
function log(x){try{fs.mkdirSync(D,{recursive:true});fs.appendFileSync(LOG,JSON.stringify(x)+'\n')}catch(_) {}}
function call(body,mode,t){try{let r=cp.spawnSync(PY,[CLIENT,CFG,mode],{input:JSON.stringify(body),encoding:'utf8',timeout:t,maxBuffer:8388608}),o;try{o=JSON.parse(r.stdout||'')}catch(_){}return{ok:r.status===0&&o,body:o,error:r.error}}catch(e){return{ok:false,error:e}}}
function main(s){let p;try{p=s.trim()?JSON.parse(s):{}}catch(e){if(s.includes('PreToolUse'))process.stdout.write(JSON.stringify({decision:'block',hookSpecificOutput:{hookEventName:'PreToolUse',permissionDecision:'deny',permissionDecisionReason:'invalid input'}}));return}let m=[],a=pid(),n=String(p.hook_event_name||''),b={event:MAP[n]||n||'hook.event',timestamp:new Date().toISOString(),pid:a,session_id:p.session_id,turn_id:p.turn_id,agent_id:p.agent_id,tool:p.tool_name,call_id:p.tool_use_id};let k=n==='UserPromptSubmit'?'prompt':n==='Stop'?'last_assistant_message':n==='PostToolUse'?'tool_response':n==='PreToolUse'?'tool_input':null;b.content=k?clean(p[k],k,k,m):null;b.content_complete=b.content!==null||n==='SessionStart';b.truncation=m.length?{truncated:true,fields:m}:{truncated:false};log(b);call(b,'event',3000);if(n==='PreToolUse'){let r=a?call({pid:a,call_id:p.tool_use_id,tool:p.tool_name,input:b.content},'decision',60000):{ok:false,error:'agent pid unresolved'},allow=!!(r.ok&&String(r.body.decision).toLowerCase()==='allow'),id=r.ok&&r.body.request_id;let q=id?call({request_id:id,applied:true,outcome:allow?'allowed':'blocked'},'ack',3000):null, c={event:'control.applied',timestamp:new Date().toISOString(),pid:a,call_id:p.tool_use_id,request_id:id||null,decision:allow?'allow':'deny',content_complete:true,ack_ok:!!(q&&q.ok)};log(c);call(c,'event',3000);if(!allow)process.stdout.write(JSON.stringify({decision:'block',hookSpecificOutput:{hookEventName:'PreToolUse',permissionDecision:'deny',permissionDecisionReason:'control unavailable or denied'}}))}}
let s='';process.stdin.on('data',x=>{if(Buffer.byteLength(s+x)<=8388608)s+=x});process.stdin.on('end',()=>main(s));

